import React, { useState } from 'react';
import { MeterGroup } from 'primereact/metergroup';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="meterGroup-accessibility">Accessible MeterGroup</label>
            <MeterGroup 
                id="meterGroup-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible MeterGroup input"
                placeholder="Enter meterGroup"
            />
        </div>
    );
}